SELECT t.flight_route_id as flightRouteId, flight_route_name as flightRouteName, kmz_storage_path as kmzUrl, type as type, t.device_code as deviceCode, (case when length(IFNULL(rel.device_name, '')) = 0 then dt.device_name else rel.device_name end ) as deviceName, t.update_time as modifiedTime, warning_type_id as warningTypeId, CASE WHEN col.collect_id IS NOT NULL THEN 0 ELSE 1 END as colStatus, kmz_file_name as kmzFileName, kmz_access_path as kmzAccessUrl, t.create_time as createTime, (case when length(IFNULL(relnest.device_name, '')) = 0 then dtl.device_name else relnest.device_name end ) as uavNestName, t.create_user as createUser, t.update_user as updateUser, t.update_time as updateTime, t.access_node as accessNode, t.is_expand_watermark AS isExpandWatermark, t.air_mileage AS airMileage, t.start_nest_code as startNestCode, t.end_nest_code as endNestCode, t.frog_leap as frogLeap, t.uav_model_code as uavModelCode FROM vm_air_line_t t LEFT JOIN vm_uav_nest_device_info dtl ON dtl.device_code = t.start_nest_code LEFT JOIN vm_uav_device_info_t dt ON t.start_nest_code = dt.uav_nest_code LEFT JOIN vm_air_line_col_t col ON t.flight_route_id = col.collect_id AND col.user_id = #{userId} and status = 0 LEFT JOIN vm_tenant_device_common_rel_t relnest ON relnest.device_code = dtl.device_code and relnest.tenant_id = #{tenantId} and relnest.industry_code = #{industryCode} and relnest.delete_flag = '0' and relnest.device_type = 4 LEFT JOIN vm_tenant_device_common_rel_t rel ON rel.device_code = dt.device_code and rel.tenant_id = #{tenantId} and rel.industry_code = #{industryCode} and rel.delete_flag = '0' and rel.device_type = 1
where t.delete_flag = 0 and t.flight_main_type = 0 and ( t.device_code in (select device_code from vm_order_uav_nest_devices where tenant_id = t.tenant_id and industry_code = t.industry_code and ord_status in (0,1,2) ) )
and flight_route_name like CONCAT(CONCAT('%', #{flightRouteName}),'%')
and t.type in
#{item}
and t.device_code in
#{item}
AND DATE_FORMAT(t.create_time,'%Y-%m-%d') >= #{createBeginTime}
AND DATE_FORMAT(t.create_time,'%Y-%m-%d') <= #{createEndTime}
and device_code = #{deviceCode}
${dataScope} order by t.create_time desc

SELECT t.flight_route_id as flightRouteId, t.flight_route_name as flightRouteName, t.uav_code as uavCode, t.device_code as deviceCode, t.access_node as accessNode FROM vm_air_line_t t where t.delete_flag = 0 and t.flight_main_type = 0
and t.device_code = #{deviceCode}
${dataScope} ORDER BY t.create_time DESC

SELECT t.flight_route_id as flightRouteId, flight_route_name as flightRouteName, kmz_storage_path as kmzUrl, type as type, t.device_code as deviceCode, (case when length(IFNULL(rel.device_name, '')) = 0 then dt.device_name else rel.device_name end ) as deviceName, t.update_time as modifiedTime, warning_type_id as warningTypeId, extra_field as kmzJson, ct.status as colStatus, kmz_file_name as kmzFileName, kmz_access_path as kmzAccessUrl, (case when length(IFNULL(relnest.device_name, '')) = 0 then dtl.device_name else relnest.device_name end ) as uavNestName, t.access_node as accessNode FROM vm_air_line_t t LEFT JOIN vm_uav_device_info_t dt ON t.start_nest_code = dt.uav_nest_code LEFT JOIN vm_uav_nest_device_info dtl ON dtl.device_code = t.start_nest_code left join vm_air_line_col_t ct on ct.collect_id = t.flight_route_id left JOIN vm_tenant_device_common_rel_t relnest ON relnest.device_code = dtl.device_code and relnest.tenant_id = #{airEditDto.tenantId} and relnest.industry_code = #{airEditDto.industryCode} and relnest.delete_flag = '0' and relnest.device_type = 4 LEFT JOIN vm_tenant_device_common_rel_t rel ON rel.device_code = dt.device_code and rel.tenant_id = #{airEditDto.tenantId} and rel.industry_code = #{airEditDto.industryCode} and rel.delete_flag = '0' and rel.device_type = 1 where ct.user_Id = #{userId} and t.flight_main_type = 0 and t.delete_flag = 0 and ct.col_type = 1 and ct.status = 0
and flight_route_name like CONCAT(CONCAT('%', #{airEditDto.flightRouteName}),'%')
and t.type = #{airEditDto.type}
and t.device_code = #{airEditDto.deviceCode}
AND DATE_FORMAT(t.create_time,'%Y-%m-%d %H:%i:%s') >= #{airEditDto.createBeginTime}
AND DATE_FORMAT(t.create_time,'%Y-%m-%d %H:%i:%s') <= #{airEditDto.createEndTime}
and t.device_code in
#{item}
${airEditDto.dataScope} order by t.create_time desc

