SELECT t.flight_route_id as flightRouteId, flight_route_name as flightRouteName, kmz_storage_path as kmzUrl, type as type, t.device_code as deviceCode, dt.id, dt.device_code as uavCode, t.update_time as modifiedTime, warning_type_id as warningTypeId, kmz_file_name as kmzFileName, kmz_access_path as kmzAccessUrl, t.create_time as createTime, dtl.device_code as uavNestCode, dtl.altitude as uavNestAltitude, t.create_user as createUser, t.update_user as updateUser, t.update_time as updateTime, t.access_node as accessNode FROM vm_air_line_t t LEFT JOIN vm_uav_nest_device_info dtl ON dtl.device_code = t.device_code LEFT JOIN vm_uav_device_info_t dt ON dt.uav_nest_code = dtl.device_code where t.delete_flag = 0 and t.flight_main_type = 0 and t.start_nest_code in
#{deviceCode}
